WITH RECURSIVE x8 AS (SELECT * FROM x10 UNION ALL SELECT * FROM x11) SELECT x5.HEX(INET_ATON('1.2.256')), x5.HEX(x3.v129319), CONCAT(LEFT(@my_uuid, 8), LEFT(x5.HEX(x3.v129319), CHAR_LENGTH(x5.HEX(x3.v129319)) - LOCATE('x', REVERSE(x5.HEX(INET_ATON('1.2.256')))))) AS x3, x5.HEX(CHAR(196)) FROM v129400 AS x5 WHERE x5.HEX(x3.v129319) < 1